def blocked_step(runtime, state) -> dict:
    """The check verdict the run stopped at: a blocked packet of the candidate, or of a failed verify_<lane>."""
    directory = runtime.directory
    pending = [item.value.get("kind") for task in state.tasks for item in task.interrupts]
    if not state.values:
        raise ValueError("The run was never started; there is no frozen lane to repair")
    if any(step.startswith("launch_") for step in state.next):
        raise ValueError("A launch step is pending or failed; use reconcile")
    if pending == ["worker_handoff"] or not (directory / "snapshots.json").exists():
        raise ValueError("A lane blocked before freeze: repair needs frozen snapshots, and an automatic run blocked there needs a new run "
                         "(RUNBOOK, Blocked after freeze: repair a lane)")
    for phase in ("worker", "candidate"):
        for node in runtime.workers:
            folder = directory / "verification" / phase / node / str(raw_attempt(directory, phase, node))
            if folder.is_dir() and not (folder / "packet.json").exists():
                raise ValueError(f"Interrupted check at {folder}; use retry --phase {phase} --node {node}")
    failed = [task.name for task in state.tasks if task.error and task.name in state.next]
    verifies = {f"verify_{node}" for node in runtime.workers}
    if failed == ["candidate"] and tuple(state.next) == ("candidate",):
        phase, nodes = "candidate", runtime.workers
    elif failed and set(state.next) <= verifies:
        phase, nodes = "worker", [name.removeprefix("verify_") for name in failed]
    else:
        raise ValueError("The run did not stop at a check verdict of the candidate or a verify_<lane> step; inspect, then retry")
    packets = []
    for node in nodes:
        attempt = raw_attempt(directory, phase, node)
        path = directory / "verification" / phase / node / str(attempt) / "packet.json"
        packet = read_json(path) if path.exists() else None
        if packet and packet["gate"]["status"] == "blocked":
            packets.append({"phase": phase, "node_id": node, "path": str(path.relative_to(directory)), "sha256": digest_file(path),
                            "attempt": attempt, "output_commit": packet["expected"]["output_commit"], "reasons": packet["gate"]["reasons"]})
    if not packets:
        raise ValueError("The failed step has no blocked packet at its current attempt, so it is not a check verdict "
                         "(an infrastructure error, a cherry-pick conflict, a partial candidate); inspect, then retry")
    return {"step": "candidate" if phase == "candidate" else ", ".join(failed), "packets": packets}


def check_source(runtime) -> None:
    """integrate()'s own checks, done early: a fix committed on the pinned source branch is outside every gate."""
    plan, repo = runtime.plan, Path(runtime.plan["repository"])
    elsewhere = f"commit fixes in a repair workspace (repair {runtime.directory} <lane> --workspace), never in the source checkout"
    branch = subprocess.run(["git", "-C", str(repo), "symbolic-ref", "-q", "--short", "HEAD"], capture_output=True, text=True).stdout.strip()
    if branch != plan["source_branch"]:
        raise ValueError(f"The source checkout is on {branch or 'a detached HEAD'}, not the run's branch {plan['source_branch']}; {elsewhere}")
    head = git(repo, "rev-parse", "HEAD")
    if head != plan["base_commit"]:
        raise ValueError(f"The source branch {branch} moved from the run's base {plan['base_commit'][:8]} to {head[:8]}, which integration "
                         f"refuses; {elsewhere}")
    if git(repo, "status", "--porcelain"):
        raise ValueError(f"The source checkout has uncommitted changes, which integration refuses; {elsewhere}")

    report = json.loads(report_path.read_text())
    def screenshot(scenario_id, attachment):
        path = Path(attachment).resolve(strict=True)
        if not path.is_relative_to(output_root.resolve()):
            raise ValueError("Screenshot attachment outside isolated browser output directory")
        return capture.add(path, "screenshot")
    counts, found, problems = scenario_evidence(report, {case["id"] for case in requirement["scenarios"]}, screenshot)
    if problems:
        raise BrowserEvidenceError(problems)
    return counts, [{"id": item["id"], "status": item["status"], "screenshot_artifact_id": item["screenshot"]} for item in found.values()]


def verify_revision(run: Path, plan: dict, policy: dict, node: str, commit: str, changed: list[str],
                    session_id: str, phase: str = "worker", attempt: int = 1) -> dict:
    """One fresh verification worktree per node/phase/attempt, artifacts retained."""
    worker = next(worker for worker in policy["workers"] if worker["node_id"] == node)
    directory = run / "verification" / phase / node / str(attempt)
    packet_path = directory / "packet.json"
    if packet_path.exists():
        packet = json.loads(packet_path.read_text())
        if packet["expected"]["output_commit"] != commit or packet["evidence"]["policy_sha256"] != policy_digest(policy):
            raise ValueError("Existing verification belongs to a different revision/policy")
        return recheck_packet(packet, policy, run)
    if directory.exists():
        raise RuntimeError("Interrupted check attempt exists; use an explicitly incremented attempt")
    directory.mkdir(parents=True, mode=0o700)
    worktree = directory / "worktree"
    git_worktree(plan["repository"], "add", "--detach", str(worktree), commit)
    if git(worktree, "rev-parse", "HEAD") != commit or git(worktree, "status", "--porcelain"):
        raise RuntimeError("Verification worktree did not start clean at expected revision")
    artifacts_dir = directory / "artifacts"
    artifacts_dir.mkdir()
    capture = Capture(artifacts_dir)
    # Captured before any check runs, so a check that rewrites a file cannot change what is recorded; the
    # post-check cleanliness rule below invalidates the evidence if one does. The candidate phase captures nothing.
    files_not_captured = capture_changed_files(worktree, changed, capture) if phase == "worker" else None
    env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
    for key in list(env):
        if key.startswith("PLAYWRIGHT_JSON_OUTPUT"):
            del env[key]  # The runner owns JSON capture, not inherited reporter paths.
    # Share installed browser executables read-only, not profiles or test caches.
    if sys.platform == "linux":
        env.setdefault("PLAYWRIGHT_BROWSERS_PATH", str(Path(env.get("XDG_CACHE_HOME", str(Path.home() / ".cache"))) / "ms-playwright"))
    env.update(PATH=str(Path(sys.executable).parent) + os.pathsep + env.get("PATH", ""),
               PYTHONDONTWRITEBYTECODE="1", NO_COLOR="1", FORCE_COLOR="0", CI="1",
               WORKFLOW_VERIFICATION_PHASE=phase)

    if database.exists():
        config = {"configurable": {"thread_id": runtime.plan["run_id"]}}
        with SqliteSaver.from_conn_string(str(database)) as saver:
            state = carry_legacy_lanes(runtime, build_pipeline(saver, runtime).get_state(config), saver)
    else:
        state = SimpleNamespace(values={}, next=tuple(f"launch_{node}" for node in runtime.workers), tasks=[])  # Prepared, never started.
    return export_state(runtime, state)


def build_pipeline(checkpointer, runtime):
    """The graph over the runtime's plan: `launch_<lane>` and `verify_<lane>` per selected lane, then the fixed tail."""
    workers = list(runtime.workers)
    def launcher(node):
        return lambda _state: {"lanes": {node: runtime.launch(node)}}
    def verifier(node):
        return lambda state: {"packets": {node: runtime.verify(node, state["snapshots"])}}
    def handoff(_state):
        message = ("Awaiting explicit completion signals and automatic freeze." if runtime.plan.get("automatic")
                   else f"Type in Claude terminals; provide a handoff for every lane ({', '.join(workers)}), then explicitly freeze.")
        decision = interrupt({"kind": "worker_handoff", "message": message})
        if decision != {"freeze": True}:
            raise ValueError("Explicit freeze required")
        return {"snapshots": runtime.freeze()}
    def candidate(state): return {"bundle": runtime.candidate(state)}
    def review(_state):
        _, digest = runtime.validate_bundle()
        if runtime.plan.get("automatic"):
            from .automatic import review_candidate
            decision = review_candidate(runtime)
        else:
            decision = interrupt({"kind": "independent_review", "bundle_sha256": digest,
                                  "bundle_path": str(runtime.directory / "review-bundle.json")})
        runtime.validate_review(decision)
        save_json(runtime.directory / "review.json", decision)
        runtime.event("review", "approved", decision["reviewer"])
        return {"review": decision}
    def approval(_state):
        _, digest = runtime.validate_bundle()
        if runtime.plan.get("automatic"):
            from .automatic import validate_automatic
            validate_automatic(runtime.plan)
            decision = {"approve": digest}  # Explicit run-level authority: feature branch only.
        else:
            decision = interrupt({"kind": "integration_approval", "bundle_sha256": digest,
                                  "message": "Approve fast-forward of source branch; no push."})
        if decision != {"approve": digest}:
            raise ValueError("Explicit exact-bundle approval required")
        return {"approved_bundle": digest}
    def integrate(state): return {"integrated_commit": runtime.integrate(state["approved_bundle"])}
    graph = StateGraph(PipelineState)
    launches = [f"launch_{node}" for node in workers]
    verifies = [f"verify_{node}" for node in workers]
    for node, name in zip(workers, launches):
        graph.add_node(name, launcher(node))
    for node, name in zip(workers, verifies):
        graph.add_node(name, verifier(node))
    for name, function in (("handoff", handoff), ("candidate", candidate), ("review", review), ("approval", approval), ("integrate", integrate)):
        graph.add_node(name, function)
    for name in launches:
        graph.add_edge(START, name)
    graph.add_edge(launches, "handoff")
    for name in verifies:
        graph.add_edge("handoff", name)
    graph.add_edge(verifies, "candidate")
    graph.add_edge("candidate", "review"); graph.add_edge("review", "approval")
    graph.add_edge("approval", "integrate"); graph.add_edge("integrate", END)
    return graph.compile(checkpointer=checkpointer)


